// RequestsSchema returns the schema of manual_journal_requests.
func RequestsSchema() *schema.Table { return &requestsTable }

// As returns a handle that references manual_journal_requests under its own alias.
func (t *RequestsTable) As(alias string) *RequestsTable {
	return keel.Alias(t.Ref, alias, BuildRequests)
}

// Lines is the many relation.
func (t *RequestsTable) Lines() *LinesTable { return keel.Path(t.Ref, 0, BuildLines) }

// Get returns the manual_journal_requests row with the given key, or keel.ErrNotFound.
func (t *RequestsTable) Get(ctx context.Context, db *keel.DB, key pulid.ID) (*manualjournal.Request, error) {
	return t.Where(t.ID.Eq(key)).One(ctx, db)
}

func newRequest() unsafe.Pointer { return unsafe.Pointer(new(manualjournal.Request)) }

func newNRequest(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]manualjournal.Request, n)))
}

func ptrRequest(p unsafe.Pointer, c int32) any {
	r := (*manualjournal.Request)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return &r.RequestNumber
	case 4:
		return (*string)(unsafe.Pointer(&r.Status))
	case 5:
		return &r.Description
	case 6:
		return &r.Reason
	case 7:
		return &r.AccountingDate
	case 8:
		return (*string)(unsafe.Pointer(&r.RequestedFiscalYearID))
	case 9:
		return (*string)(unsafe.Pointer(&r.RequestedFiscalPeriodID))
	case 10:
		return &r.CurrencyCode
	case 11:
		return &r.TotalDebit
	case 12:
		return &r.TotalCredit
	case 13:
		return &r.ApprovedAt
	case 14:
		return (*string)(unsafe.Pointer(&r.ApprovedByID))
	case 15:
		return &r.RejectedAt
	case 16:
		return (*string)(unsafe.Pointer(&r.RejectedByID))
	case 17:
		return &r.RejectionReason
	case 18:
		return &r.CancelledAt
	case 19:
		return (*string)(unsafe.Pointer(&r.CancelledByID))
	case 20:
		return &r.CancelReason
	case 21:
		return (*string)(unsafe.Pointer(&r.PostedBatchID))
	case 22:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 23:
		return (*string)(unsafe.Pointer(&r.UpdatedByID))
	case 24:
		return &r.Rank
	case 25:
		return &r.Version
	case 26:
		return &r.CreatedAt
	case 27:
		return &r.UpdatedAt
	}
	return nil
}

func valueRequest(p unsafe.Pointer, c int32) any {
	r := (*manualjournal.Request)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return r.RequestNumber
	case 4:
		return string(r.Status)
	case 5:
		return r.Description
	case 6:
		if r.Reason == "" {
			return nil
		}
		return r.Reason
	case 7:
		return r.AccountingDate
	case 8:
		return string(r.RequestedFiscalYearID)
	case 9:
		return string(r.RequestedFiscalPeriodID)
	case 10:
		return r.CurrencyCode
	case 11:
		return r.TotalDebit
	case 12:
		return r.TotalCredit
	case 13:
		if r.ApprovedAt == nil {
			return nil
		}
		return *r.ApprovedAt
	case 14:
		if r.ApprovedByID == "" {
			return nil
		}
		return string(r.ApprovedByID)
	case 15:
		if r.RejectedAt == nil {
			return nil
		}
		return *r.RejectedAt
	case 16:
		if r.RejectedByID == "" {
			return nil
		}
		return string(r.RejectedByID)
	case 17:
		if r.RejectionReason == "" {
			return nil
		}
		return r.RejectionReason
	case 18:
		if r.CancelledAt == nil {
			return nil
		}
		return *r.CancelledAt
	case 19:
		if r.CancelledByID == "" {
			return nil
		}
		return string(r.CancelledByID)
	case 20:
		if r.CancelReason == "" {
			return nil
		}
		return r.CancelReason
	case 21:
		if r.PostedBatchID == "" {
			return nil
		}
		return string(r.PostedBatchID)
	case 22:
		return string(r.CreatedByID)
	case 23:
		if r.UpdatedByID == "" {
			return nil
		}
		return string(r.UpdatedByID)
	case 24:
		return r.Rank
	case 25:
		return r.Version
	case 26:
		return r.CreatedAt
	case 27:
		return r.UpdatedAt
	}
	return nil
}

func attachRequest(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*manualjournal.Request)(p)
	switch rel {
	case 0:
		r.Lines = append(r.Lines, (*manualjournal.Line)(child))
	}
}

func beforeCreateRequest(ctx context.Context, p unsafe.Pointer) error {
	return (*manualjournal.Request)(p).BeforeCreate(ctx)
}

func init() {
	linesTable.Relations[0].Target = glaccountdb.GLAccountsSchema()
	requestsTable.Relations[0].Target = LinesSchema()
}

// intIs64 fails the build where int is not 64 bits: int fields are read through *int64.
const intIs64 = unsafe.Sizeof(int(0)) - 8

var enumStatus = [...]schema.EnumValue{
	{Value: `Draft`, Label: `Draft`},
	{Value: `PendingApproval`, Label: `Pending Approval`},
	{Value: `Approved`, Label: `Approved`},
	{Value: `Rejected`, Label: `Rejected`},
	{Value: `Cancelled`, Label: `Cancelled`},
	{Value: `Posted`, Label: `Posted`},
}

// StatusCol is a column of manualjournal.Status values.
type StatusCol struct{ keel.StringCol }

func (c StatusCol) Eq(v manualjournal.Status) keel.Pred  { return c.StringCol.Eq(string(v)) }
func (c StatusCol) Ne(v manualjournal.Status) keel.Pred  { return c.StringCol.Ne(string(v)) }
func (c StatusCol) Gt(v manualjournal.Status) keel.Pred  { return c.StringCol.Gt(string(v)) }
func (c StatusCol) Gte(v manualjournal.Status) keel.Pred { return c.StringCol.Gte(string(v)) }
func (c StatusCol) Lt(v manualjournal.Status) keel.Pred  { return c.StringCol.Lt(string(v)) }
func (c StatusCol) Lte(v manualjournal.Status) keel.Pred { return c.StringCol.Lte(string(v)) }
func (c StatusCol) IsDistinctFrom(v manualjournal.Status) keel.Pred {
	return c.StringCol.IsDistinctFrom(string(v))
}
func (c StatusCol) Between(lo, hi manualjournal.Status) keel.Pred {
	return c.StringCol.Between(string(lo), string(hi))
}
func (c StatusCol) To(v manualjournal.Status) keel.Assignment { return c.StringCol.To(string(v)) }
func (c StatusCol) In(vs ...manualjournal.Status) keel.Pred {
	return c.StringCol.In(keel.Strings(vs)...)
}
func (c StatusCol) NotIn(vs ...manualjournal.Status) keel.Pred {
	return c.StringCol.NotIn(keel.Strings(vs)...)
}
